create table if not exists public.gl_impact(gl_impact_id bigint generated always as identity primary key,transaction_id bigint not null references public."transaction"(transaction_id) on delete cascade,account_id bigint not null references public.chart_accounts(account_id),subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),fiscal_period_id bigint not null references public.fiscal_periods(fiscal_period_id),accounting_book_id bigint not null references public.accounting_books(accounting_book_id),debit_amount numeric(24,6) not null default 0 check(debit_amount>=0),credit_amount numeric(24,6) not null default 0 check(credit_amount>=0),debit_fx numeric(24,6) not null default 0 check(debit_fx>=0),credit_fx numeric(24,6) not null default 0 check(credit_fx>=0),posting_date date not null,check(debit_amount>0 or credit_amount>0));
create table if not exists public.journal(journal_id bigint generated always as identity primary key,journal_number text not null unique,journal_date date not null,transaction_id bigint references public."transaction"(transaction_id) on delete set null,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),currency_id bigint not null references public.currencies(currency_id),fiscal_period_id bigint not null references public.fiscal_periods(fiscal_period_id),exchange_rate numeric(24,10) not null default 1 check(exchange_rate>0),memo text);
create table if not exists public.journal_line(journal_line_id bigint generated always as identity primary key,journal_id bigint not null references public.journal(journal_id) on delete cascade,account_id bigint not null references public.chart_accounts(account_id),debit numeric(24,6) not null default 0 check(debit>=0),credit numeric(24,6) not null default 0 check(credit>=0),debit_fx numeric(24,6) not null default 0 check(debit_fx>=0),credit_fx numeric(24,6) not null default 0 check(credit_fx>=0),department_id bigint references public.departments(department_id),class_id bigint references public.classes(class_id),location_id bigint references public.locations(location_id),check(debit>0 or credit>0));
do $$declare t text;begin foreach t in array array['gl_impact','journal','journal_line']loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "accounting_select" on public.%I',t);execute format('drop policy if exists "accounting_insert" on public.%I',t);execute format('drop policy if exists "accounting_update" on public.%I',t);execute format('drop policy if exists "accounting_delete" on public.%I',t);execute format('create policy "accounting_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "accounting_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "accounting_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "accounting_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
